-- ADR 0088, the care mode: a fan in distress is answered with care, every answer validated by a human, until a manager
-- or the owner closes it. `care_opened` and `care_closed` journal it; the conversation projects when the open episode
-- began, when its help bubble went out, and when the last one was closed. The two type checks take the new types.
ALTER TABLE "conversation_events" DROP CONSTRAINT "conversation_events_type_check";--> statement-breakpoint
ALTER TABLE "domain_events" DROP CONSTRAINT "domain_events_type_check";--> statement-breakpoint
ALTER TABLE "conversations" ADD COLUMN "care_since" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "conversations" ADD COLUMN "care_help_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "conversations" ADD COLUMN "care_closed_at" timestamp with time zone;--> statement-breakpoint
